-- Fire-and-forget: badge values editor (TODO-style list) field labels and
-- tooltips on /configurations/create. All keys in system.translations,
-- 7 languages. Idempotent via partial unique index (key, language)
-- WHERE deleted_at IS NULL.

BEGIN;

ON CONFLICT (key, language) WHERE deleted_at IS NULL DO UPDATE SET value = EXCLUDED.value, updated_at = now();

COMMIT;
